gwa(){return"\ub192\uc74c"},
gwd(){return"\uac80\ud1a0 \ud544\uc694"},
gwb(){return"\ub9e4\uc6b0 \uc2e0\ub8b0\ud560 \uc218 \uc788\uc74c"},
