got(){return"\uc758\uc2ec\uc2a4\ub7ec\uc6c0"},
gou(){return"\ub192\uc74c"},
gov(){return"\uc911\uac04"},
gos(){return"\ub2e8\uc77c \ubb38\uc790, \ud398\uc774\uc9c0 \ubc88\ud638, \uc139\uc158 \ubc88\ud638, \ub108\ubb34 \uc9e7\uc740 OCR/PDF \uc870\uac01\uc740 \uc81c\uc678\ub418\uc5c8\uc2b5\ub2c8\ub2e4."},
op(a){return""+a+"\uac1c \ud56d\ubaa9"},
