goz(){return"\ubb38\uc7a5 \ub2e8\uc704 \ubaa8\ub378 \uc2e0\ud638\uac00 \ub192\uc74c"},
ow(a){return"\uc6d0\ubcf8 \uc704\uce58 "+a},
