vk(a,b){return a+': \uc720\uc0ac\ud55c \ud6c4\ubcf4 "'+b+'"\uc744(\ub97c) \ucc3e\uc558\uc9c0\ub9cc, \uc800\uc790, \uc5f0\ub3c4 \ub610\ub294 \uc81c\ubaa9\uc774 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc77c\uce58 \uc784\uacc4\uac12\uc744 \ucda9\uc871\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.'},
vj(a){return a+": \uac80\uc99d \uc18c\uc2a4\uac00 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc751\ub2f5\uc744 \ubc18\ud658\ud558\uc9c0 \uc54a\uc558\uac70\ub098 \ud56d\ubaa9 \uc815\ubcf4\uac00 \ubd80\uc871\ud569\ub2c8\ub2e4. TruthLens\ub294 \uc774 \uc778\uc6a9\uc744 \uac80\uc99d\ub41c \uac83\uc73c\ub85c \uac04\uc8fc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gw0(){return"\ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0 \uc0c1\ud0dc\uac00 \uc88b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4"},
gw_(){return"\uc774 \uc571\uc740 \uc2e4\ud589 \uc2dc \uae30\ubcf8\uc801\uc73c\ub85c \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc774 \uc788\ub2e4\uace0 \uac00\uc815\ud569\ub2c8\ub2e4. \ud558\uc774\ud37c\ub9c1\ud06c \ubc0f \uc778\uc6a9 \ubb38\ud5cc \uc2e4\uc7ac\uc131 \ubd84\uc11d\uc740 \uacb0\uacfc\ub97c \ud310\uc815\ud558\uae30 \uc704\ud574 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \ud604\uc7ac \uc5f0\uacb0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ub124\ud2b8\uc6cc\ud06c \uc0c1\ud0dc\ub97c \ud655\uc778\ud55c \ud6c4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
gwe(){return"\uc5f0\uacb0 \ub2e4\uc2dc \ud655\uc778"},
on(a,b,c){return"\ucd1d "+a+"\ubb38\uc7a5\nAI \uc758\uc2ec "+b+"\ubb38\uc7a5\n\uc0ac\ub78c "+c+"\ubb38\uc7a5"},
