grL(){return"4\uac1c \uc5d4\uc9c4 \ubcd1\ub82c \ucd94\ub860"},
grN(){return"\uc2e4\uc2dc\uac04 \uc9c4\ud589\ub960"},
grM(){return"ESL \uc791\ubb38 \ubcf4\uc815"},
grO(){return"\uc5b8\uc81c\ub4e0\uc9c0 \uc911\uc9c0 \uac00\ub2a5"},
grT(){return"AI \uac1c\uc694 \uac8c\uc774\uc9c0"},
grU(){return"\ubb38\uc7a5 \ud788\ud2b8\ub9f5"},
grR(){return"\ubb38\ud5cc \uac80\uc99d"},
