gtD(){return"\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0430\u044f"},
tN(a,b,c,d){return a+" \xb7 "+b+" \xb7 \u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f "+c+" \u0413\u0411 \u041e\u0417\u0423 \xb7 v"+d},
tO(a,b,c){return"\u0420\u0430\u0437\u043c\u0435\u0440: "+a+" \xb7 \u0422\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440: "+b+" \xb7 \u0418\u043d\u0434\u0435\u043a\u0441 \u043c\u0435\u0442\u043a\u0438 \u0418\u0418: "+c},
