tH(a){return"\u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c ("+a+")"},
gtC(){return"\u0421\u043a\u043e\u0440\u043e"},
gn1(){return"\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0439"},
gtP(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
gn0(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c"},
gtL(){return"\u0421\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u043c\u043e\u0434\u0435\u043b\u0438"},
gtK(){return"\u041c\u043e\u0436\u0435\u0442 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u0442\u044c \u043e\u0431\u044a\u0451\u043c \u043f\u0430\u043c\u044f\u0442\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430"},
tJ(a){return"\u041e\u0448\u0438\u0431\u043a\u0430: "+a},
gn_(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u043c\u043e\u0434\u0435\u043b\u044c?"},
tF(a,b){return'\u042d\u0442\u043e \u0443\u0434\u0430\u043b\u0438\u0442 "'+a+'" ('+b+"). \u0412\u0430\u043c \u043f\u0440\u0438\u0434\u0451\u0442\u0441\u044f \u0441\u043a\u0430\u0447\u0430\u0442\u044c \u0435\u0451 \u0441\u043d\u043e\u0432\u0430, \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c."},
tG(a,b){return'\u042d\u0442\u043e \u0443\u0434\u0430\u043b\u0438\u0442 \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0443\u044e \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c "'+a+'" ('+b+"). \u0412\u0430\u043c \u043f\u0440\u0438\u0434\u0451\u0442\u0441\u044f \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0435\u0451 \u0441\u043d\u043e\u0432\u0430, \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c."},
gkG(){return"\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438"},
